/* From Uiverse.io by abassj1 - Tags: button */
/* Modified code from @gagan-gv */
.__UIV_SCOPE__ .button {
 padding: 1em 2em;
 font-size: 17px;
 background: transparent;
 border: none;
 position: relative;
 color: yellow;
 z-index: 1;
}

.__UIV_SCOPE__ .button::after,
 .__UIV_SCOPE__ .button::before {
 content: '';
 position: absolute;
 bottom: 0;
 right: 0;
 z-index: -99999;
 transition: all .4s;
}

.__UIV_SCOPE__ .button::before {
 transform: translate(0%, 0%);
 width: 100%;
 height: 100%;
 background: darkslategray;
 border-radius: 50px;
}

.__UIV_SCOPE__ .button::after {
 transform: translate(0px, 0px);
 width: 10px;
 height: 10px;
 background: #ffffff15;
 backdrop-filter: blur(5px);
 border-radius: 50px;
}

.__UIV_SCOPE__ .button:hover::before {
 transform: translate(5%, 20%);
 width: 10px;
 height: 10px;
}

.__UIV_SCOPE__ .button:hover::after {
 border-radius: 50px;
 transform: translate(0, 0);
 width: 100%;
 height: 100%;
}

.__UIV_SCOPE__ .button:active::after {
 transition: 0s;
 transform: translate(0, 5%);
}
